code.source:
#include <iostream>
using namespace std;

int main() {
    int day = 3;
    switch (day) {
        case 1: cout << "Monday" << endl; break;
        case 2: cout << "Tuesday" << endl; break;
        case 3: cout << "Wednesday" << endl; break;
        default: cout << "Another day" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    char choice = 'b';
    switch (choice) {
        case 'a':
        case 'A':
            cout << "Add" << endl;
            break;
        case 'b':
        case 'B':
            cout << "Buy" << endl;
            break;
        default:
            cout << "Unknown" << endl;
    }
    return 0;
}

